#!/usr/bin/env bash
# convert-languages.sh
# Switches the site's languages to the new xx-XX.json format:
#  - src/locales/<code>.json  →  src/locales/<lang>-<REGION>.json (tab-indented)
#  - each file = all keys from the new languages files + all web texts
#    (the web texts for all 35 languages are built into this script, so they are
#     added even if the old en.json/no.json/… files are already gone)
#  - the "-------EOF-----------" key stays last
#  - the title is HEADACHE_DIARY ("Hodepinedagboken") in every language, also on the dashboard and in the browser tab
#  - i18n.js, LocaleGate, AboutAppModal and layout.js use the new codes
#    (old cookies like "no"/"sv" are mapped to "nb-NO"/"sv-SE")
# Run from the project root:
#   bash convert-languages.sh path/to/languages    (folder or .zip with en-US.json, nb-NO.json, …)
#   bash convert-languages.sh                      (uses the xx-XX.json files already in src/locales)
set -euo pipefail

if [ ! -f src/lib/i18n.js ]; then
  echo "✗ src/lib/i18n.js not found – run this from the project root." >&2
  exit 1
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

SRC="${1:-src/locales}"
if [ -f "$SRC" ]; then
  unzip -q "$SRC" -d "$TMP/unzipped"
  SRC="$TMP/unzipped"
fi
LANG_DIR="$(find "$SRC" -name en-US.json -not -path '*__MACOSX*' -exec dirname {} \; | head -1)"
if [ -z "$LANG_DIR" ]; then
  echo "✗ No en-US.json found in $SRC – pass the languages folder or zip:" >&2
  echo "  bash convert-languages.sh path/to/languages" >&2
  exit 1
fi
echo "Using languages from: $LANG_DIR"

# ---------------------------------------------------------------- web texts (all 35 languages)
cat > "$TMP/web-keys.json" <<'FILE_END'
