# ---------------------------------------------------------------- merge files
cat > "$TMP/merge.mjs" <<'FILE_END'
import fs from "node:fs";
import path from "node:path";

const [langDir, localesDir, webFile] = process.argv.slice(2);
const OLD = {
  "ar-SA": "ar", "bg-BG": "bg", "bs-BA": "bs", "ca-ES": "ca", "cs-CZ": "cs", "da-DK": "da",
  "de-DE": "de", "el-GR": "el", "en-US": "en", "es-ES": "es", "et-EE": "et", "fi-FI": "fi",
  "fr-FR": "fr", "he-IL": "he", "hr-HR": "hr", "hu-HU": "hu", "is-IS": "is", "it-IT": "it",
  "ja-JP": "ja", "lt-LT": "lt", "lv-LV": "lv", "mk-MK": "mk", "nb-NO": "no", "nl-NL": "nl",
  "pl-PL": "pl", "pt-BR": "pt-BR", "pt-PT": "pt", "ro-RO": "ro", "ru-RU": "ru", "sk-SK": "sk",
  "sl-SI": "sl", "sr-RS": "sr", "sv-SE": "sv", "tr-TR": "tr", "uk-UA": "uk",
};
const EOF_KEY = "-------EOF-----------";
const read = (f) => JSON.parse(fs.readFileSync(f, "utf8").replace(/^﻿/, ""));
const WEB = read(webFile);

for (const [code, oldCode] of Object.entries(OLD)) {
  const appFile = path.join(langDir, `${code}.json`);
  const outFile = path.join(localesDir, `${code}.json`);
  const oldFile = path.join(localesDir, `${oldCode}.json`);
  if (!fs.existsSync(appFile)) throw new Error(`Missing ${appFile}`);

  // Web texts: built-in, overridden by an old file if it is still there (keeps local edits)
  const web = { ...WEB[code] };
  if (oldFile !== outFile && fs.existsSync(oldFile)) Object.assign(web, read(oldFile));
  // The title is the app's own name (HEADACHE_DIARY), also in the help text
  delete web.LANDING_TITLE;
  web.PATIENT_CODE_HELP_TEXT = WEB[code].PATIENT_CODE_HELP_TEXT;

  const app = read(appFile);
  const merged = {};
  for (const [k, v] of Object.entries(app)) if (k !== EOF_KEY && k !== "LANDING_TITLE" && !(k in web)) merged[k] = v;
  Object.assign(merged, web);
  if (EOF_KEY in app) merged[EOF_KEY] = app[EOF_KEY];

  fs.writeFileSync(outFile, JSON.stringify(merged, null, "\t") + "\n");
  if (oldFile !== outFile && fs.existsSync(oldFile)) fs.unlinkSync(oldFile);
  console.log(`✓ src/locales/${code}.json  (${Object.keys(merged).length} keys)`);
}
FILE_END
node "$TMP/merge.mjs" "$LANG_DIR" src/locales "$TMP/web-keys.json"

# ---------------------------------------------------------------- i18n.js
cat > src/lib/i18n.js <<'FILE_END'
// src/lib/i18n.js
import arSA from "@/locales/ar-SA.json";
import bgBG from "@/locales/bg-BG.json";
import bsBA from "@/locales/bs-BA.json";
